import { test } from 'node:test';
import assert from 'node:assert/strict';
import { discoverPacks } from '../engine/pack_loader/pack-registry.mjs';
import { ENGINE_VERSION, isDeclaredVersion, versionAbove } from '../engine/version.mjs';

// Every canon pack declares both version fields. The manifest spec cannot require
// them — a member's own local packs are repo-owned, carry no version, and nothing
// would carry a fix if the loader started rejecting them (DESIGN §8) — so the
// "canon packs are versioned" half is asserted here, over the canon tree, where it
// is the only tree the claim is about.
//
// Runs against the REAL pack set rather than a fixture: a fixture would keep proving
// that a manifest CAN carry a version while a newly added pack silently shipped
// without one. Discovered with no `localRoot`, so the home's own local packs — which
// are exactly the unversioned kind — stay out of scope.
test('every canon pack declares a version and the engine version it needs', async () => {
  const { packs } = await discoverPacks();
  assert.ok(packs.length > 20, `only ${packs.length} packs discovered — this test is asserting over the wrong tree`);

  for (const pack of packs) {
    assert.ok(isDeclaredVersion(pack.version),
      `pack "${pack.id}" declares no version — add a date-anchored "version" to packs/${pack.id}/pack.mjs`);
    assert.ok(isDeclaredVersion(pack.minEngineVersion),
      `pack "${pack.id}" declares no minEngineVersion — add "minEngineVersion: 1" to packs/${pack.id}/pack.mjs`);
    // A pack that asks for an engine newer than the one it ships beside could never
    // apply anywhere: the canon is the newest engine that exists.
    assert.ok(!versionAbove(pack.minEngineVersion, ENGINE_VERSION),
      `pack "${pack.id}" requires engine version ${pack.minEngineVersion}, above the canon's own ${ENGINE_VERSION}`);
  }
});
=== rule-index ===
// The rule index a pack README carries: one row per rule in the pack's
// RULES.md, each row stating that rule's length, the severity of ignoring
// it and the reason it exists (packs/README.md#the-rule-index-a-pack-readme-carries).
//
// A rule's length is derived data, so it is computed here and compared against
// the README by rule-index.test.mjs rather than hand-maintained in the two dozen
// pack READMEs whose prose is appended to several times a week. The row states
// the size BAND rather than the count, because nothing reads the digit: the
// session-start summary counts the prose itself and no other reader opens this
// index, so an exact figure only bought a red build every time a rule moved by
// one word (#2006).

// The two closed vocabularies a row's Severity and Reason cells are drawn from,
// spelled once here and described in packs/README.md.
export const SEVERITIES = ['critical', 'high', 'medium', 'low'];
export const REASONS = ['correctness', 'performance', 'complexity', 'legal'];

// The ladder a rule's length is reported on: an upper bound per rung, and an
// open top so no length is unclassifiable. The corpus reaches ~200 words today,
// so the last two rungs stand empty — kept because a rule that grows past 200
// should find its rung already there rather than force a change to this ladder.
export const SIZE_BOUNDS = [20, 50, 100, 200, 500];
export const SIZES = [...SIZE_BOUNDS.map((n) => `<${n}`), `${SIZE_BOUNDS.at(-1)}+`];

export function proseSize(words) {
  const bound = SIZE_BOUNDS.find((n) => words < n);
  return bound ? `<${bound}` : `${SIZE_BOUNDS.at(-1)}+`;
}

const RULE_BULLET = /^- \*\*/;

