import { test } from 'node:test';
import assert from 'node:assert/strict';
import rule, { publishPrefixes, touchesPublishSet } from '../workRules/version-bumped.mjs';

const ORCHESTRATOR = '.github/workflows/static-site-release.yml';
const CONFIG = '.github/site.config';

const config = (extra = '') => [
  'publish_root=site',
  'publish_paths=index.html assets',
  'version_files=package.json',
  'build_command=',
  'test_command=',
  extra,
].filter(Boolean).join('\n');

const pkg = (version) => `{\n  "name": "demo",\n  "version": "${version}"\n}\n`;

// The work context a work rule receives — only the members this rule reads.
const work = (changedFiles, files, base) => ({
  changedFiles,
  read: (f) => files[f] ?? null,
  readBase: (f) => base[f] ?? null,
});

const siteFiles = (version, extra = {}) => ({
  [ORCHESTRATOR]: 'name: Release static site\n',
  [CONFIG]: config(),
  'package.json': pkg(version),
  ...extra,
});

const run = (changed, head, base = head) => rule.run(work(changed, siteFiles(head), { 'package.json': pkg(base) }));

// --- what counts as a published change ---------------------------------------

test('publish prefixes are resolved against publish_root, as the deploy resolves them', () => {
  const values = new Map([['publish_root', 'site'], ['publish_paths', 'index.html assets']]);
  assert.deepEqual(publishPrefixes(values), ['site/index.html', 'site/assets']);
});
=== rule text ===
}

const rule = {
  id: 'sw/version-bumped',
  severity: 'blocking',
  scope: 'work',
  description: 'A change to the published site raises the site version in the same change',
  doc: 'packs/static-website/skills/shipping-a-static-site/SKILL.md',
  why: 'the release flow releases the version it finds on main and never writes one, so a published change that does not raise the version is never released — the pipeline no-ops on a version it has already shipped',

  run(work) {
    if (!adoptedStandard(work)) return [];
    const configText = work.read(CONFIG_PATH);
    if (configText === null) return [];          // sw/site-config owns a missing or broken config
    const { values } = parseConfig(configText);

    const prefixes = publishPrefixes(values);
    if (!prefixes.length) return [];
    const touched = touchesPublishSet(work.changedFiles, prefixes);
    if (!touched.length) return [];

