1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	import { parseConfig } from '../stubs/actions/read-site-config/read-config.mjs';
3	
4	// The pack's own vendored surface: the PR gate and the three composite actions
5	// that read `.github/site.config`, build the publish set and compute the version.
6	// They are materialized into each site repo's own .github/ because GitHub resolves
7	// a composite action only from a repo's own .github/, never from the shared mount
8	// — so "the logic lives in the pack" means the pack holds the templates and each
9	// repo hosts a managed copy: edit the pack, not the copy.
10	//
11	// Whatever SERVES the site is another pack's business (github-pages for Pages,
12	// cloudflare-site for Cloudflare); everything named here is true of a static site
13	// whichever one it is.
14	export const CI_STUB_FILE = 'static-site-ci.yml';
15	export const VENDORED_ACTIONS = ['read-site-config', 'bump-site-version', 'assemble-site'];
16	export const CONFIG_PATH = '.github/site.config';
17	
18	export const stubPath = (file) => `.github/workflows/${file}`;
19	
20	// TWO INDEPENDENT SIGNALS, either sufficient — because the artifact this pack's
21	// checks most need to catch missing IS one of them. Gating on `site.config` alone
22	// would let a repo that vendored the pipeline and never wrote its config pass
23	// silently, which is the one case `sw/site-config` exists to report.
24	export function adoptedStandard(ctx) {
25	  return ctx.read(CONFIG_PATH) !== null; // MUTATION: single signal
26	}
27	
28	const rule = {
29	  id: 'sw/vendored-pipeline',
30	  severity: 'blocking',
31	  description: 'The PR gate and the composite actions that read the site config must be vendored into .github/',
32	  doc: 'packs/static-website/skills/shipping-a-static-site/SKILL.md',
33	  why: 'the config, the version and the publish set are read by local composite actions — a missing one is a build that cannot resolve what the repo declared, and a missing gate is a publish set nothing checks before it merges',
34	
35	  run(ctx) {
36	    if (!adoptedStandard(ctx)) return [];
37	    const out = [];
38	
39	    for (const action of VENDORED_ACTIONS) {
40	      const file = `.github/actions/${action}/action.yml`;
41	      if (ctx.read(file) === null) {
42	        out.push(finding(rule, {
43	          file,
44	          what: 'missing — the vendored workflows read the site config through this local composite action',
45	          fix: `copy it (and the files beside it) from the pack's stubs/actions/${action}/`,
46	        }));
47	      }
48	    }
49	
50	    // The gate. A repo whose site deploys on merge with nothing checking the pull
51	    // request publishes whatever merged. Any CI workflow satisfies it: a repo that
52	    // already runs its own suite need not take this one. `tracked` is git's own
53	    // file list, so an as-yet-unadded workflow does not count as present.
54	    if (ctx.read(stubPath(CI_STUB_FILE)) === null
55	      && !ctx.tracked.some((f) => /^\.github\/workflows\/.*ci.*\.ya?ml$/i.test(f))) {
56	      out.push(finding(rule, {
57	        file: stubPath(CI_STUB_FILE),
58	        what: 'missing — a repo that deploys what reaches its default branch has no gate unless its pull requests run one',
59	        fix: `copy the pack's stubs/workflows/${CI_STUB_FILE} (conformance sweep + the repo's gate + the publish-set assembly dry run)`,
60	      }));
61	    }
62	
63	    // build_vars is opt-in, and so is this: a repo that never declares one is
64	    // untouched by the exporter's arrival and stays on its older vendored copy
65	    // quite happily. Declaring one is the moment the older copy becomes WRONG —
66	    // it reads the key, ignores it, and builds with the variable unset — and
67	    // that failure is silent all the way to the live page, so it is caught here
68	    // instead. This is the shape to reuse when a stub gains a capability: gate
69	    // the conformance on the repo having asked for it.
70	    const cfg = ctx.read(CONFIG_PATH);
71	    if (cfg !== null && parseConfig(cfg).values.get('build_vars')?.trim()) {
72	      const exporter = `.github/actions/${VENDORED_ACTIONS[0]}/export-build-vars.mjs`;
73	      if (ctx.read(exporter) === null) {
74	        out.push(finding(rule, {
75	          file: exporter,
76	          what: `missing, but ${CONFIG_PATH} declares build_vars — the vendored action predates the exporter, so the declared variables reach the build as nothing at all`,
77	          fix: `copy it from the pack's stubs/actions/${VENDORED_ACTIONS[0]}/ (re-copy the whole directory, the action.yml gained an output too)`,
78	        }));
79	      }
80	      const ci = ctx.read(stubPath(CI_STUB_FILE));
81	      if (ci !== null && !ci.includes('export-build-vars.mjs')) {
82	        out.push(finding(rule, {
83	          file: stubPath(CI_STUB_FILE),
84	          what: 'runs build_command without exporting the build_vars the config declares — the build sees none of them',
85	          fix: `re-copy it from the pack's stubs/workflows/${CI_STUB_FILE}`,
86	        }));
87	      }
88	    }
89	    return out;
90	  },
91	};
92	
93	export default rule;

