// The release's gate: has the default branch moved since the last release went out?
//
// This is the task's own term because no built-in asks the question a release asks.
// `substantive-change` excludes task-authored commits, so a recount another task
// landed — a real change to what the site serves — would read as silence and never
// ship. `any-commit` includes them but measures a WINDOW, so the release's own bump
// commit keeps the window non-empty and every night re-releases the same bytes under
// a fresh version number.
//
// What ends that loop is position, not membership: the newest release commit is a
// high-water mark, and only what sits above it is unreleased. That is the same guard
// `[skip ci]` used to be, stated as a fact about the branch rather than as a flag on
// a commit message — nothing can accidentally re-arm a release by rewording a commit.

// Which commits are the release's own, read structurally off the `Claudinite-Task:`
// trailer every task-authored commit carries. The worker stamps it from the queue's
// own `CLAUDINITE_PACK`/`CLAUDINITE_TASK`; the test holds this literal against the
// two directory names those are derived from.
export const RELEASE_TASK_ID = 'cloudflare-site/site-release';

// The `commits` signal lists the window's default-branch commits NEWEST FIRST — the
// order the GitHub commits API returns and the collector preserves — which is what
// makes "above the high-water mark" a slice.
export function unreleasedCommits(list = []) {
  const mark = list.findIndex((c) => c?.task === RELEASE_TASK_ID);
  return (mark === -1 ? list : list.slice(0, mark)).filter((c) => c?.task !== RELEASE_TASK_ID);
}

export const terms = {
  'unreleased-commits': {
    signals: ['commits'],
    holds(signals) {
      const list = signals?.commits?.list ?? [];
      const unreleased = unreleasedCommits(list);
      if (!unreleased.length) {
        return {
          holds: false,
          reason: list.length
            ? 'the newest default-branch commit is the last release itself — nothing has landed since it'
            : 'no commit landed on the default branch in the window',
        };
      }
      return {
        holds: true,
        reason: `${unreleased.length} commit(s) landed on the default branch since the last release`,
        context: [`Releasing ${unreleased.length} commit(s), newest first: ${unreleased.map((c) => String(c.sha ?? '?').slice(0, 7)).join(', ')}.`],
      };
    },
  },
};
=== worker
// site-release — cut a version, publish the site tree to Cloudflare, record the release.
//
// The whole run is deterministic: read the branch tip, advance the version, push that
// bump, upload the tree. Nothing here is a judgment call, which is why the task runs
// no agent — and nothing here is a marketplace action either: `wrangler deploy` is a
// CLI, so the release needs no workflow of its own and lives entirely in the queue.
//
// ORDER IS DELIBERATE: the bump lands on the branch BEFORE the upload. Either half
// can fail, and of the two possible drifts only one is silent — a site serving a
// version the repo has no record of. A consumed version number that never shipped is
// visible in the park and costs nothing; the next release simply takes the next one.

import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { removeTree } from '../../../../engine/remove-tree.mjs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
// Reading a branch tip without disturbing the executor's checkout, and stamping the
// trailer that says which task wrote a commit, are claudinite-tasks' to own; a local
// copy would be a second implementation of the one thing that must not have two. The
// published `public/` seam is the only way a pack may reach another's code, and
// the relative path resolves the same from the canon and from a member's mount.
import { baseTip, readAt, remoteUrl, withTaskTrailer } from '../../../claudinite-tasks/public/delivery.mjs';
import { BEACON_PLACEHOLDER, claimedHostnames, parseWranglerConfig, publishedDir, wranglerConfigPath } from '../../lib.mjs';
import { nextVersion, stampHtml } from '../../bump-version.mjs';
import { preflight } from './preflight.mjs';

// Pinned rather than floating: a release that silently changes its own toolchain
// between two nights is a change nobody reviewed.
export const WRANGLER = 'wrangler@4.128.0';

// Re-exported so a member reading the worker finds the placeholder where it is used;
// `lib.mjs` owns it, because the check keeping a real token out of the tree names it
// too (see there).
export { BEACON_PLACEHOLDER };
// Cloudflare's beacon tokens are hex. Anything else would be substituted into a string
// literal in a served script, so it is refused rather than shipped.
const BEACON_SHAPE = /^[0-9a-f]{8,}$/i;

// How many times the bump push re-reads the tip and rebuilds before giving up. The
// scheduler and the maintenance PRs also land on the default branch, and a lost race
// here would leave the repo naming an older version than the one being served.
const PUSH_ATTEMPTS = 5;

const log = (m) => console.log(`site-release: ${m}`);

const git = (cwd, args, opts = {}) => execFileSync('git', ['-C', cwd, ...args], {
  encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, ...opts,
});

// The deployment as the commit at `sha` declares it: which config wrangler will read,
// which tree it uploads, and which hostnames it claims. Read from the commit rather
// than the checkout, so the release describes what it is about to ship.
export function deploymentAt(root, sha) {
  const tracked = git(root, ['ls-tree', '-r', '--name-only', sha]).split('\n').filter(Boolean);
  const configPath = wranglerConfigPath(tracked);
  if (!configPath) {
    console.error('claudinite-needs-human: decision — no wrangler.json/.jsonc at the repo root or one directory down, so nothing declares what the release uploads');
    throw new Error('no wrangler config on the branch');
  }
  const config = parseWranglerConfig(readAt(root, sha, configPath));
  const dir = publishedDir(config, configPath);
  if (!dir) {
    console.error(`claudinite-needs-human: decision — ${configPath} declares no assets.directory, so the release has no tree to upload`);
    throw new Error(`${configPath} declares no assets.directory`);
  }
  return { configPath, dir, hostnames: claimedHostnames(config), tracked };
}

// A commit carrying `files` on top of `parent`, built through a scratch index so the
// executor's checkout and working tree are never touched.
function commitOnto(root, { parent, files, message }) {
  const index = join(tmpdir(), `claudinite-release-${process.pid}-${Date.now()}.index`);
  const plumb = (args, opts) => git(root, args, { ...opts, env: { ...process.env, GIT_INDEX_FILE: index } });
  try {
    plumb(['read-tree', parent]);
    for (const [path, content] of Object.entries(files)) {
      const blob = git(root, ['hash-object', '-w', '--stdin'], { input: content }).trim();
      plumb(['update-index', '--add', '--cacheinfo', `100644,${blob},${path}`]);
    }
    const tree = plumb(['write-tree']).trim();
    return git(root, [
      '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
      'commit-tree', tree, '-p', parent, '-m', message,
    ]).trim();
  } finally { rmSync(index, { force: true }); }
}

// Advance the version on `base` and push it, rebuilding on top of whatever landed
// under us. The version is recomputed from each attempt's tip rather than carried
// across, so a release that raced another writer still counts from what is there.
//
// Deliberately not `pushGenerated`: that lane force-pushes, which is correct for a
// regenerate-not-reconcile branch and catastrophic for the default branch.
export function pushRelease(root, { remote, base, taskId, now = new Date() }) {
  let lastError = null;
  for (let attempt = 1; attempt <= PUSH_ATTEMPTS; attempt += 1) {
    const parent = baseTip(root, remote, base);
    const pkgText = readAt(root, parent, 'package.json');
    if (pkgText === null) {
      console.error(`claudinite-needs-human: decision — package.json is absent from ${base}, so there is no version to advance`);
      throw new Error(`package.json is absent from ${base}`);
    }
    const pkg = JSON.parse(pkgText);
    const version = nextVersion(pkg.version, now);
    const deployment = deploymentAt(root, parent);

    const files = { 'package.json': `${JSON.stringify({ ...pkg, version }, null, 2)}\n` };
    for (const page of deployment.tracked.filter((p) => p.startsWith(`${deployment.dir}/`) && p.endsWith('.html'))) {
      const html = readAt(root, parent, page);
      if (html === null) continue;
      const stamped = stampHtml(html, version);
      if (stamped !== html) files[page] = stamped;
    }

    const commit = commitOnto(root, {
      parent,
      files,
      message: withTaskTrailer(`Release site version ${version}`, taskId),
    });
    try {
      git(root, ['push', '--quiet', remote, `${commit}:refs/heads/${base}`]);
      return { version, commit, attempts: attempt, deployment };
    } catch (e) {
      lastError = e;
      log(`push rejected on attempt ${attempt} — ${base} moved; rebuilding on its new tip`);
    }
  }
  throw new Error(`could not push the version bump after ${PUSH_ATTEMPTS} attempts: ${lastError?.message ?? 'unknown'}`);
}

// The exact tree that is about to be uploaded, checked out beside the repo so the
// deployed bytes are the released commit's and nothing else's.
function withReleaseTree(root, commit, fn) {
  const dir = mkdtempSync(join(tmpdir(), 'claudinite-release-'));
  git(root, ['worktree', 'add', '--detach', '--quiet', dir, commit]);
  try { return fn(dir); } finally {
    try { git(root, ['worktree', 'remove', '--force', dir]); } catch { removeTree(dir); }
  }
}

// Substitute the beacon token into every file of the copy being uploaded that carries
// the placeholder. Returns whether analytics will actually be live on this release —
// the placeholder surviving is the documented off state, not a failure, and saying
// which happened is the only way a run where the beacon never engaged is
// distinguishable from one where it did.
export function injectBeacon(treeDir, files, token) {
  if (!token) return false;
  if (!BEACON_SHAPE.test(token)) {
    console.error('claudinite-needs-human: action — the CLOUDFLARE_ANALYTICS_TOKEN repository variable is not a Cloudflare beacon token (hex); fix or clear it');
    throw new Error('CLOUDFLARE_ANALYTICS_TOKEN is malformed');
  }
  let injected = 0;
  for (const file of files) {
    const path = join(treeDir, file);
    let text;
    try { text = readFileSync(path, 'utf8'); } catch { continue; }
    if (!text.includes(BEACON_PLACEHOLDER)) continue;
    writeFileSync(path, text.split(BEACON_PLACEHOLDER).join(token));
    injected += 1;
  }
  if (!injected) {
    console.error(`claudinite-needs-human: decision — the CLOUDFLARE_ANALYTICS_TOKEN variable is set, but no published file carries the ${BEACON_PLACEHOLDER} placeholder, so the token has nowhere to go`);
    throw new Error('the analytics placeholder is gone');
  }
  return true;
}

// A wrangler failure a person can fix in seconds (a token without the right scope, an
// account id that is not theirs, a zone that is not on Cloudflare yet) versus one that
// needs the trace read. The park lane follows from this.
export const isOperatorFailure = (output) => /\b(10000|10001|10021)\b|authentication error|not authorized|unauthorized|permission|no such zone|could not find zone/i.test(output ?? '');

function deploy(dir, { apiToken, accountId }) {
  try {
    const out = execFileSync('npx', ['--yes', WRANGLER, 'deploy'], {
      cwd: dir,
      encoding: 'utf8',
      maxBuffer: 64 * 1024 * 1024,
      env: {
        ...process.env,
        CLOUDFLARE_API_TOKEN: apiToken,
        CLOUDFLARE_ACCOUNT_ID: accountId,
        WRANGLER_SEND_METRICS: 'false',
        CI: 'true',
      },
    });
    console.log(out);
    return out;
  } catch (e) {
    const output = `${e.stdout ?? ''}\n${e.stderr ?? ''}`;
    console.log(output);
    console.error(isOperatorFailure(output)
      ? 'claudinite-needs-human: action — Cloudflare refused the upload; check the CLOUDFLARE_API_TOKEN scopes, the CLOUDFLARE_ACCOUNT_ID, and that the claimed domain is a zone on this account'
      : 'claudinite-needs-human: failure — wrangler deploy failed; the output above is the trace');
    throw new Error(`wrangler deploy failed: ${e.message}`);
  }
}

// What the hostnames served after the upload. A release is not finished when the API
// returns 200: the point of the exercise is that a visitor reaches the page, and the
// run is the only place that is ever checked. A first attach issues a certificate,
// which takes minutes, so this REPORTS rather than parks — the version is already
// cut and the upload already happened, and there is nothing here to undo.
export async function reportServed(hostnames, { fetchImpl = fetch } = {}) {
  const served = [];
  for (const hostname of hostnames) {
    try {
      const res = await fetchImpl(`https://${hostname}/`, { redirect: 'follow' });
      served.push({ hostname, status: res.status });
    } catch (e) { served.push({ hostname, error: e.message }); }
  }
  return served;
}

export async function main() {
  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
  const repo = process.env.CLAUDINITE_REPO;
  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
  const taskId = `${process.env.CLAUDINITE_PACK}/${process.env.CLAUDINITE_TASK}`;
  const token = process.env.GITHUB_TOKEN;
  const apiToken = process.env.CLOUDFLARE_API_TOKEN;
  const accountId = process.env.CLOUDFLARE_ACCOUNT_ID;

  if (!repo) throw new Error('CLAUDINITE_REPO is not set (owner/repo)');
  if (!token) throw new Error('GITHUB_TOKEN is not set — the release cannot read the branch tip or push its bump');
  if (!apiToken || !accountId) {
    console.error('claudinite-needs-human: action — CLOUDFLARE_API_TOKEN and CLOUDFLARE_ACCOUNT_ID must both be configured as repository secrets before the site can be published');
    throw new Error('the Cloudflare credentials are not configured');
  }

  // Before the version is consumed: what the previous host left on the hostnames
  // this deploy claims.
  const claimed = deploymentAt(root, baseTip(root, remoteUrl(repo, token), base)).hostnames;
  const { blocked, unprobed } = await preflight(claimed);
  if (unprobed.length) log(`could not resolve ${unprobed.join(', ')} — the inherited-record probe did not run for ${unprobed.length === 1 ? 'it' : 'them'}`);
  if (blocked.length) {
    for (const b of blocked) log(`${b.what} — ${b.fix}`);
    console.error(`claudinite-needs-human: action — ${blocked.map((b) => b.what).join('; ')}. ${blocked.map((b) => b.fix).join(' ')}`);
    throw new Error('a claimed hostname still answers from the previous host');
  }

  const { version, commit, attempts, deployment } = pushRelease(root, { remote: remoteUrl(repo, token), base, taskId });
  log(`released version ${version} as ${commit.slice(0, 7)}${attempts > 1 ? ` (after ${attempts} push attempts)` : ''}`);

  withReleaseTree(root, commit, (dir) => {
    const published = deployment.tracked.filter((p) => p.startsWith(`${deployment.dir}/`));
    const live = injectBeacon(dir, published, process.env.CLOUDFLARE_ANALYTICS_TOKEN);
    log(live
      ? 'injected the Cloudflare Web Analytics beacon token — analytics is live on this release'
      : 'no CLOUDFLARE_ANALYTICS_TOKEN variable — the placeholder ships and analytics stays off');
    const configDir = deployment.configPath.includes('/')
      ? join(dir, deployment.configPath.slice(0, deployment.configPath.lastIndexOf('/')))
      : dir;
    deploy(configDir, { apiToken, accountId });
  });

  for (const r of await reportServed(deployment.hostnames)) {
    log(r.error ? `https://${r.hostname}/ did not answer: ${r.error}` : `https://${r.hostname}/ answered ${r.status}`);
  }
  log(`published ${deployment.dir} at version ${version}`);
}

// Run only when invoked directly (code-work's `node worker.mjs`), never on import.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => { console.error(`site-release failed: ${e.message}`); process.exit(1); });
}
=== lib
// What the repo's own wrangler config says about the deployment: which tree is
// published, and which hostnames the Worker claims. Every other file in this pack
// asks these two questions, and none of them asks the repo to repeat the answers
// as config — the config file wrangler already reads is the one source.
//
// JSON only (`wrangler.json`/`wrangler.jsonc`). A TOML config is a legitimate
// wrangler setup and simply not one this pack reads: parsing a second
// configuration language to answer two questions buys nothing that moving the
// config does not, and `publishes-a-site-directory` says so where a repo meets it.

// The config filenames wrangler resolves, in its own precedence order.
export const WRANGLER_CONFIGS = ['wrangler.json', 'wrangler.jsonc'];

// The config in `paths`, at the repo root or one directory down — the same reach
// the cloudflare-workers pack fingerprints on, so a stray config in a fixture or
// example tree deeper in the tree is not mistaken for the deployment's.
export function wranglerConfigPath(paths = []) {
  const candidates = paths.filter((p) => {
    const parts = p.split('/');
    return parts.length <= 2 && WRANGLER_CONFIGS.includes(parts[parts.length - 1]);
  });
  // Shallowest first, then the extension order wrangler itself prefers.
  candidates.sort((a, b) => a.split('/').length - b.split('/').length
    || WRANGLER_CONFIGS.indexOf(a.split('/').pop()) - WRANGLER_CONFIGS.indexOf(b.split('/').pop()));
  return candidates[0] ?? null;
}

// JSONC to JSON: drop `//` and `/* */` comments that are not inside a string.
// Hand-written because the whole need is two comment forms over a file wrangler
// itself accepts, and a dependency for that is a dependency to keep.
export function stripJsonComments(text) {
  let out = '';
  let inString = false;
  let inLine = false;
  let inBlock = false;
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i];
    const next = text[i + 1];
    if (inLine) { if (c === '\n') { inLine = false; out += c; } continue; }
    if (inBlock) { if (c === '*' && next === '/') { inBlock = false; i += 1; } continue; }
    if (inString) {
      out += c;
      if (c === '\\') { out += next ?? ''; i += 1; } else if (c === '"') inString = false;
      continue;
    }
    if (c === '"') { inString = true; out += c; continue; }
    if (c === '/' && next === '/') { inLine = true; i += 1; continue; }
    if (c === '/' && next === '*') { inBlock = true; i += 1; continue; }
    out += c;
  }
  return out;
}

// The parsed config, or null when it is absent or unparseable — the callers all
// have something to say about that themselves.
export function parseWranglerConfig(text) {
  if (typeof text !== 'string') return null;
  try { return JSON.parse(stripJsonComments(text)); } catch { return null; }
}

// The published tree, as a repo-relative path: `assets.directory` resolved against
// the directory holding the config, exactly as wrangler resolves it.
export function publishedDir(config, configPath = 'wrangler.json') {
  const dir = config?.assets?.directory;
  if (typeof dir !== 'string' || !dir.trim()) return null;
  const base = configPath.includes('/') ? `${configPath.slice(0, configPath.lastIndexOf('/'))}/` : '';
  const normalized = dir.replace(/^\.\//, '').replace(/\/+$/, '');
  return `${base}${normalized}`;
}

// The hostnames the deploy attaches as custom domains — the ones a visitor types,
// and the ones a record inherited from a previous host can block or shadow.
export function claimedHostnames(config) {
  const routes = Array.isArray(config?.routes) ? config.routes : [];
  return routes
    .filter((r) => r && r.custom_domain === true && typeof r.pattern === 'string')
    .map((r) => r.pattern);
}

// The Cloudflare Web Analytics beacon token is public — it ships in the client — so it
// rides a repository VARIABLE and is substituted into the copy being uploaded, never
// into the commit. A loader carrying this placeholder no-ops while it is still in
// place. Here rather than in the release worker because the check that keeps a real
// token out of the tree names it too, and a check may not drag a task's worker (and
// its imports) into every sweep.
export const BEACON_PLACEHOLDER = 'REPLACE_WITH_CLOUDFLARE_WEB_ANALYTICS_TOKEN';
=== rest of bump
}

// One page's stamp. A page carrying no `title="version …"` is returned unchanged —
// it has not asked for the version, and nothing is inserted into markup here.
export function stampHtml(html, version) {
  return html.replace(STAMP, `title="version ${version}"`);
}

// Stamp every page under `dir`, recursively, in place. Returns the paths it rewrote.
export function stampPages(dir, version) {
  const stamped = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) { stamped.push(...stampPages(path, version)); continue; }
    if (!entry.name.endsWith('.html')) continue;
    const html = readFileSync(path, 'utf8');
    const next = stampHtml(html, version);
    if (next === html) continue;
    writeFileSync(path, next);
    stamped.push(path);
  }
  return stamped;
}

// The published tree of the repo at `repoRoot`, read from its wrangler config.
export function repoPublishedDir(repoRoot) {
  for (const name of WRANGLER_CONFIGS) {
    let text;
    try { text = readFileSync(join(repoRoot, name), 'utf8'); } catch { continue; }
    const dir = publishedDir(parseWranglerConfig(text), name);
    if (dir) return dir;
  }
  return null;
}

// Advance `package.json` and stamp the published pages under `repoRoot`, returning
// the new version. `stampOnly` re-stamps from the version already recorded.
export function bump(repoRoot, { now = new Date(), stampOnly = false } = {}) {
  const pkgPath = join(repoRoot, 'package.json');
  const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'));
  const version = stampOnly ? pkg.version : nextVersion(pkg.version, now);
  if (!stampOnly) writeFileSync(pkgPath, `${JSON.stringify({ ...pkg, version }, null, 2)}\n`);
  const dir = repoPublishedDir(repoRoot);
  if (dir) stampPages(join(repoRoot, dir), version);
  return version;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  // Run from the repo it is bumping: the mount sits at .claudinite/shared/packs/<id>/,
  // so `--root` names the checkout when the cwd is not it.
  const flag = process.argv.indexOf('--root');
  const root = flag === -1 ? process.env.CLAUDE_PROJECT_DIR || process.cwd() : process.argv[flag + 1];
  console.log(bump(root, { stampOnly: process.argv.includes('--stamp-only') }));
}

