=== public/github.mjs
// The GitHub client a task's worker lands its output with, the Actions environment it
// reads its repo and run from, and the tracker issue it records progress on —
// published for other packs so a worker reaches GitHub the same way the executor does.
//
// The client and two operations, not the port: a worker that needs a further REST
// call asks for the operation to be published rather than composing a path, which is
// what keeps every path this pack calls countable in `src/world/github.mjs`.
export {
  makeGh, dispatchWorkflow,
} from '../src/world/github.mjs';
export {
  SCHEDULER_WORKFLOW_FILE, EXECUTOR_WORKFLOW_FILE,
} from '../src/world/actions.mjs';
export {
  findOrCreateTracker, writeTracker,
} from '../src/items/tracker.mjs';
=== public/workflow-failure.mjs
// PUBLIC ENTRY POINT — a command, never logic.
//
// Named as a literal path by something this repository cannot rewrite: a member's
// `.github/workflows/`, which lands only as a pull request somebody merges; a
// routine's stored prompt, which is a per-repo console setting; or prose in a
// member's own local pack, which no converge may touch. A member spends every
// window between its mount refreshing (nightly) and those being re-pointed
// (whenever) running whichever path it still names — so a run that finds nothing
// here is a repo whose queue stops silently, with no run left to fix it.
//
// `public/` is where that promise is kept: a name here does not move, and nothing
// may put behaviour behind one. The mechanism lives under `src/`.
//
// The scheduler workflow's `report-failure` job: a run that went red as a whole
// reaches a person as one open issue rather than an unwatched red tab.

import { pathToFileURL } from 'node:url';
import { runWorkflowFailureReport } from '../src/recover/workflow-failure.mjs';

export * from '../src/recover/workflow-failure.mjs';
// The surface this path published, named rather than left to the star: a member's
// own local pack may import it, and `export *` says nothing a reader — or the
// consumer-safe-change check — can see.
export {
  runWorkflowFailureReport, reportWorkflowFailure, findOpenFailureIssue, runUrl,
  FAILURE_LABELS, WORKFLOW_FAILURE, SCHEDULER_FAILURE_TITLE,
} from '../src/recover/workflow-failure.mjs';

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  runWorkflowFailureReport().catch((e) => { console.error(e.message ?? e); process.exit(1); });
