// The version scheme and the page stamp left this pack for public-website, and the
// release now advances the version only where THAT pack is declared. A member that
// adopted cloudflare-site when it still carried the scheme keeps its versioning
// through this record: every repo declaring cloudflare-site is made to declare
// public-website too, once, so no release goes out unversioned because a pack moved.
//
// Additive and idempotent: a member already declaring public-website is untouched,
// and a member that later undeclares it is making the unversioned choice on purpose
// — the record only ever adds, from the tree the record itself first landed in.
const DECLARATIONS = ['.claudinite-settings.json', '.claudinite-checks.json'];

const declaresCloudflareSite = async (read) => {
  for (const file of DECLARATIONS) {
    const raw = await read(file);
    if (raw == null) continue;
    try {
      const packs = JSON.parse(raw)?.packs;
      return Array.isArray(packs) && packs.some((e) => (typeof e === 'string' ? e : e?.id) === 'cloudflare-site');
    } catch { return false; }
  }
  return false;
};

export default {
  id: 'cloudflare-site-keeps-its-version',
  landed: '2026-09-17',
  version: 1,
  summary: 'a repo serving from Cloudflare declares public-website, which now owns the version its release advances',

  appliesTo: declaresCloudflareSite,

  declarePacks: [{ id: 'public-website' }],

  // Nothing to leave behind: a declaration once added stays, and the record adds it
  // only where cloudflare-site is declared without it.
  legacyPresent: async (read) => {
    if (!(await declaresCloudflareSite(read))) return false;
    for (const file of DECLARATIONS) {
      const raw = await read(file);
      if (raw == null) continue;
      try {
        const packs = JSON.parse(raw)?.packs ?? [];
        return !packs.some((e) => (typeof e === 'string' ? e : e?.id) === 'public-website');
      } catch { return false; }
    }
    return false;
  },
};

