  id: 'cloudflare-site-keeps-its-version',
  landed: '2026-09-17',
  version: 1,
  summary: 'a repo serving from Cloudflare declares public-website, which now owns the version its release advances',

  appliesTo: declaresCloudflareSite,

  declarePacks: [{ id: 'public-website' }],

  // Nothing to leave behind: a declaration once added stays, and the record adds it
  // only where cloudflare-site is declared without it.
  legacyPresent: async (read) => {
    if (!(await declaresCloudflareSite(read))) return false;
    for (const file of DECLARATIONS) {
      const raw = await read(file);
